// Parses the FIA's 2026 F1 documents page and returns only the newsworthy documents not seen
// before (same parsing and filter as scripts/fia-docs.mjs). Seen URLs live in the workflow's
// static data, which n8n only saves on production (active) runs, not on manual test runs.
const NEWSWORTHY = /infringement|decision|offence|summons|penalt|pit lane|grid|reprimand|disqualif|appeal|right of review|classification/i;
const html = String($input.first().json.data ?? '');
const event = (html.match(/event-title active">([^<]+)</) || [])[1]?.trim() ?? '(unknown event)';
const re = /<a href="(\/system\/files\/decision-document\/[^"]+)"[\s\S]*?<div class="title">\s*([\s\S]*?)\s*<\/div>[\s\S]*?date-display-single">([^<]+)</g;
const docs = [...html.matchAll(re)].map(([, href, title, published]) => ({
  url: `https://www.fia.com${href}`,
  title: title.replace(/\s+/g, ' ').trim(),
  published: `${published.trim()} CET`,
}));
if (!docs.length) throw new Error('No FIA documents parsed: the page layout may have changed');

const state = $getWorkflowStaticData('global');
const firstRun = !Array.isArray(state.seen);
const seen = new Set(state.seen ?? []);
state.seen = docs.map((d) => d.url);
if (firstRun) return []; // first production run only records what is already there

const fresh = docs.filter((d) => !seen.has(d.url) && NEWSWORTHY.test(d.title));
if (!fresh.length) return [];
const list = fresh.map((d) => `<li><b>${d.title}</b><br>${d.published} · <a href="${d.url}">PDF</a></li>`).join('');
return [{ json: {
  subject: `FIA ${event}: ${fresh.length === 1 ? fresh[0].title : fresh.length + ' new documents'}`,
  html: `<p>${event} · ${fresh.length} new FIA document(s)</p><ul>${list}</ul><p>Source: fia.com decision documents. Read the PDF before publishing.</p>`,
} }];
